import sqlite3
import json
from pathlib import Path

# ============================================================================
# CIV6 DISTRICT PLACEMENT OPTIMIZER
# ============================================================================

# Configuration
SCENARIO_FILE = '/data/scenario_3/scenario.json'
OUTPUT_FILE = '/output/scenario_3.json'

# Map parameters
MAP_WIDTH = 44
MAP_HEIGHT = 26

# City working range
CITY_WORKING_RANGE = 3

# Terrain constants
BUILDABLE_TERRAIN = {'TERRAIN_GRASS', 'TERRAIN_PLAINS', 'TERRAIN_COAST'}
MOUNTAIN_TERRAIN = {'TERRAIN_GRASS_MOUNTAIN'}

# District types available for single city with pop 9
AVAILABLE_DISTRICTS = ['CAMPUS', 'COMMERCIAL_HUB', 'INDUSTRIAL_ZONE', 'HOLY_SITE', 'THEATER_SQUARE']

# Adjacency bonus rules
DISTRICT_BONUSES = {
    'CAMPUS': {
        'TERRAIN_GRASS_MOUNTAIN': 1,
        'FOREST': 1,
        'CAMPUS': 0.5,  # Per adjacent
    },
    'COMMERCIAL_HUB': {
        'RIVER': 2,
        'COAST': 1,
        'TRADABLE_RESOURCE': 1,
        'COMMERCIAL_HUB': 0.5,
    },
    'INDUSTRIAL_ZONE': {
        'TERRAIN_GRASS_MOUNTAIN': 1,
        'RESOURCE': 1,
        'INDUSTRIAL_ZONE': 0.5,
    },
    'HOLY_SITE': {
        'TERRAIN_GRASS_MOUNTAIN': 1,
        'RAINFOREST': 1,
        'HOLY_SITE': 0.5,
    },
    'THEATER_SQUARE': {
        'WONDER': 1,
        'WATER': 0.5,
        'THEATER_SQUARE': 0.5,
    }
}

# ============================================================================
# LOAD DATA
# ============================================================================

with open(SCENARIO_FILE, 'r') as f:
    scenario = json.load(f)

map_file = f"/data/{scenario['map_file']}"
conn = sqlite3.connect(map_file)
cursor = conn.cursor()

# Load terrain map
def id_to_coords(plot_id, width):
    y = plot_id // width
    x = plot_id % width
    return x, y

cursor.execute("SELECT ID, TerrainType FROM Plots ORDER BY ID")
plots = cursor.fetchall()

terrain_map = [[None for _ in range(MAP_WIDTH)] for _ in range(MAP_HEIGHT)]
for plot_id, terrain_type in plots:
    x, y = id_to_coords(plot_id, MAP_WIDTH)
    terrain_map[y][x] = terrain_type

# ============================================================================
# UTILITY FUNCTIONS
# ============================================================================

def get_adjacent_tiles(x, y):
    adjacent = []
    for dx in [-1, 0, 1]:
        for dy in [-1, 0, 1]:
            if dx == 0 and dy == 0:
                continue
            nx, ny = x + dx, y + dy
            if 0 <= nx < MAP_WIDTH and 0 <= ny < MAP_HEIGHT:
                adjacent.append((nx, ny))
    return adjacent

def is_buildable(x, y):
    """Check if tile can have a district placed on it."""
    if not (0 <= x < MAP_WIDTH and 0 <= y < MAP_HEIGHT):
        return False
    terrain = terrain_map[y][x]
    # COAST can have entertainment complex/harbor
    # Most districts need GRASS or PLAINS
    return terrain in BUILDABLE_TERRAIN

def is_in_city_range(city_x, city_y, tile_x, tile_y):
    """Check if tile is within working range of city center."""
    dist = max(abs(city_x - tile_x), abs(city_y - tile_y))
    return dist <= CITY_WORKING_RANGE

def calculate_campus_bonus(x, y, placements):
    """Calculate adjacency bonus for CAMPUS."""
    bonus = 0
    adjacent = get_adjacent_tiles(x, y)

    for ax, ay in adjacent:
        # Mountain bonus
        if 'MOUNTAIN' in terrain_map[ay][ax]:
            bonus += 1

    return bonus

def calculate_commercial_hub_bonus(x, y, placements):
    """Calculate adjacency bonus for COMMERCIAL_HUB."""
    bonus = 0
    adjacent = get_adjacent_tiles(x, y)

    for ax, ay in adjacent:
        terrain = terrain_map[ay][ax]
        # Coast adjacency (1 bonus per coast tile)
        if terrain == 'TERRAIN_COAST':
            bonus += 1

    return bonus

def calculate_industrial_zone_bonus(x, y, placements):
    """Calculate adjacency bonus for INDUSTRIAL_ZONE."""
    bonus = 0
    adjacent = get_adjacent_tiles(x, y)

    for ax, ay in adjacent:
        # Mountain bonus
        if 'MOUNTAIN' in terrain_map[ay][ax]:
            bonus += 1

    return bonus

def calculate_holy_site_bonus(x, y, placements):
    """Calculate adjacency bonus for HOLY_SITE."""
    bonus = 0
    adjacent = get_adjacent_tiles(x, y)

    for ax, ay in adjacent:
        # Mountain bonus
        if 'MOUNTAIN' in terrain_map[ay][ax]:
            bonus += 1

    return bonus

def calculate_theater_square_bonus(x, y, placements):
    """Calculate adjacency bonus for THEATER_SQUARE."""
    bonus = 0
    adjacent = get_adjacent_tiles(x, y)

    for ax, ay in adjacent:
        terrain = terrain_map[ay][ax]
        # Water adjacency
        if terrain in {'TERRAIN_OCEAN', 'TERRAIN_COAST'}:
            bonus += 1

    return bonus

BONUS_CALCULATORS = {
    'CAMPUS': calculate_campus_bonus,
    'COMMERCIAL_HUB': calculate_commercial_hub_bonus,
    'INDUSTRIAL_ZONE': calculate_industrial_zone_bonus,
    'HOLY_SITE': calculate_holy_site_bonus,
    'THEATER_SQUARE': calculate_theater_square_bonus,
}

def calculate_total_bonus(placements, city_center):
    """Calculate total adjacency bonus for all placements."""
    total = 0
    bonuses = {}

    for district_type, (x, y) in placements.items():
        if district_type in BONUS_CALCULATORS:
            bonus = BONUS_CALCULATORS[district_type](x, y, placements)
            bonuses[district_type] = bonus
            total += bonus
        else:
            bonuses[district_type] = 0

    return total, bonuses

# ============================================================================
# FIND BEST CITY CENTER
# ============================================================================

# Find buildable tiles
buildable_tiles = []
for y in range(MAP_HEIGHT):
    for x in range(MAP_WIDTH):
        if is_buildable(x, y):
            buildable_tiles.append((x, y))

print(f"Total buildable tiles: {len(buildable_tiles)}")

# Score each tile as a potential city center based on nearby mountains
# (good for CAMPUS and other districts)
city_center_scores = {}
for x, y in buildable_tiles:
    nearby_mountains = 0
    for dx in range(-CITY_WORKING_RANGE, CITY_WORKING_RANGE + 1):
        for dy in range(-CITY_WORKING_RANGE, CITY_WORKING_RANGE + 1):
            nx, ny = x + dx, y + dy
            if 0 <= nx < MAP_WIDTH and 0 <= ny < MAP_HEIGHT:
                if 'MOUNTAIN' in terrain_map[ny][nx]:
                    nearby_mountains += 1
    city_center_scores[(x, y)] = nearby_mountains

# Select best city center
best_city_center = max(buildable_tiles, key=lambda t: city_center_scores[t])
print(f"Best city center: {best_city_center} with {city_center_scores[best_city_center]} nearby mountains")

# ============================================================================
# PLACE DISTRICTS OPTIMALLY
# ============================================================================

city_center = best_city_center
city_x, city_y = city_center

# Get all tiles within city range that are buildable
available_tiles = []
for y in range(MAP_HEIGHT):
    for x in range(MAP_WIDTH):
        if (x, y) != city_center and is_buildable(x, y) and is_in_city_range(city_x, city_y, x, y):
            available_tiles.append((x, y))

print(f"Available tiles for districts: {len(available_tiles)}")

# Greedy placement: place districts to maximize bonuses
# Population 9 typically allows multiple districts (4-5)
placements = {}
used_tiles = {city_center}

# Try to place CAMPUS first (highest potential for bonuses with mountains)
campus_scores = {}
for x, y in available_tiles:
    if (x, y) not in used_tiles:
        bonus = calculate_campus_bonus(x, y, placements)
        campus_scores[(x, y)] = bonus

if campus_scores:
    best_campus = max(available_tiles, key=lambda t: campus_scores.get(t, 0))
    if campus_scores[best_campus] > 0:
        placements['CAMPUS'] = best_campus
        used_tiles.add(best_campus)
        print(f"Placed CAMPUS at {best_campus} with bonus {campus_scores[best_campus]}")

# Try to place COMMERCIAL_HUB next (coast bonuses)
commercial_scores = {}
for x, y in available_tiles:
    if (x, y) not in used_tiles:
        bonus = calculate_commercial_hub_bonus(x, y, placements)
        commercial_scores[(x, y)] = bonus

if commercial_scores:
    best_commercial = max(available_tiles, key=lambda t: commercial_scores.get(t, 0))
    if commercial_scores[best_commercial] > 0:
        placements['COMMERCIAL_HUB'] = best_commercial
        used_tiles.add(best_commercial)
        print(f"Placed COMMERCIAL_HUB at {best_commercial} with bonus {commercial_scores[best_commercial]}")

# Try to place INDUSTRIAL_ZONE (mountain bonuses)
industrial_scores = {}
for x, y in available_tiles:
    if (x, y) not in used_tiles:
        bonus = calculate_industrial_zone_bonus(x, y, placements)
        industrial_scores[(x, y)] = bonus

if industrial_scores:
    best_industrial = max(available_tiles, key=lambda t: industrial_scores.get(t, 0))
    if industrial_scores[best_industrial] > 0:
        placements['INDUSTRIAL_ZONE'] = best_industrial
        used_tiles.add(best_industrial)
        print(f"Placed INDUSTRIAL_ZONE at {best_industrial} with bonus {industrial_scores[best_industrial]}")

# Try to place HOLY_SITE (mountain bonuses)
holy_scores = {}
for x, y in available_tiles:
    if (x, y) not in used_tiles:
        bonus = calculate_holy_site_bonus(x, y, placements)
        holy_scores[(x, y)] = bonus

if holy_scores:
    best_holy = max(available_tiles, key=lambda t: holy_scores.get(t, 0))
    if holy_scores[best_holy] > 0:
        placements['HOLY_SITE'] = best_holy
        used_tiles.add(best_holy)
        print(f"Placed HOLY_SITE at {best_holy} with bonus {holy_scores[best_holy]}")

# Try to place THEATER_SQUARE (water adjacency)
theater_scores = {}
for x, y in available_tiles:
    if (x, y) not in used_tiles:
        bonus = calculate_theater_square_bonus(x, y, placements)
        theater_scores[(x, y)] = bonus

if theater_scores:
    best_theater = max(available_tiles, key=lambda t: theater_scores.get(t, 0))
    if theater_scores[best_theater] > 0:
        placements['THEATER_SQUARE'] = best_theater
        used_tiles.add(best_theater)
        print(f"Placed THEATER_SQUARE at {best_theater} with bonus {theater_scores[best_theater]}")

# ============================================================================
# CALCULATE FINAL BONUSES
# ============================================================================

total_adjacency, adjacency_bonuses = calculate_total_bonus(placements, city_center)

print(f"\n=== SOLUTION ===")
print(f"City center: {city_center}")
print(f"Placements: {placements}")
print(f"Adjacency bonuses: {adjacency_bonuses}")
print(f"Total adjacency: {total_adjacency}")

# ============================================================================
# WRITE OUTPUT
# ============================================================================

output = {
    "city_center": list(city_center),
    "placements": {k: list(v) for k, v in placements.items()},
    "adjacency_bonuses": adjacency_bonuses,
    "total_adjacency": total_adjacency
}

Path('/output').mkdir(exist_ok=True)
with open(OUTPUT_FILE, 'w') as f:
    json.dump(output, f, indent=2)

print(f"\nOutput written to {OUTPUT_FILE}")

conn.close()
SOLUTION
